    $ana->tenants()->attach($acme);
    $beto->tenants()->attach($acme);
    $bruno->tenants()->attach($globex);
    $carla->tenants()->attach([$acme->id, $globex->id]);

    return compact('acme', 'globex', 'ana', 'beto', 'bruno', 'carla');
